def caponLocalizedInput (m : ℕ) (i₀ j₀ : Fin (2 ^ m))
    (p : ℝ≥0∞) [Fact (1 ≤ p)] (N : ℕ) : MixedNorm ℝ p :=
  tensorWith (caponLocalLeaf m j₀ (N + 1)) (caponLocalAverage m i₀ p N)

